#!/bin/sh
# SHA256SUMS over docs/research/futoi/atlas/ ONLY.
#
# This folder is separate from the closed M1/M2 run: the closed run's own
# SHA256SUMS is NOT touched or regenerated by this script, and this manifest
# does not cover anything outside this folder.
#
# Excluded, each for a stated reason:
#   SHA256SUMS      cannot contain its own digest
#   logs/           filenames carry run timestamps
#   __pycache__/    build output, not a deliverable
#   .fullrun_log    a one-line pointer written by the driver
# Paths are relative to this folder, so the manifest is checkable with:
#     cd docs/research/futoi/atlas && sha256sum -c SHA256SUMS
set -eu
cd "$(dirname "$0")"
find . -type f \
     ! -name SHA256SUMS \
     ! -path './logs/*' \
     ! -path './__pycache__/*' \
     ! -name '*.pyc' \
     ! -name '.fullrun_log' \
     ! -name '*.tmp' \
  | LC_ALL=C sort \
  | xargs sha256sum > SHA256SUMS
echo "files hashed: $(wc -l < SHA256SUMS)"
echo "logs/ excluded: $(find ./logs -type f 2>/dev/null | wc -l) files (run-timestamped names)"
